 static MontoyaApi api;static WorkbenchExtension ext;static Path out;static String base="http://127.0.0.1:18299";static final List<Map<String,Object>> checks=new ArrayList<>(),journey=new ArrayList<>(),gaps=new ArrayList<>();static final List<AutoCloseable> cleanup=new ArrayList<>();static final Set<String> profiles=new TreeSet<>();static int nativeSends,proxySends;static RuntimeUserAudit.Account alice,bob;
 interface Work{void run()throws Exception;}
 static void edt(Runnable r)throws Exception{SwingUtilities.invokeAndWait(r);}
 static Object field(Object o,String n)throws Exception{var f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}
 static Object invoke(Object o,String n)throws Exception{var m=o.getClass().getDeclaredMethod(n);m.setAccessible(true);return m.invoke(o);}
 static void check(String n,boolean yes,Object d){checks.add(Map.of("name",n,"passed",yes,"detail",String.valueOf(d)));if(!yes)throw new AssertionError(n+": "+d);}
 static void gap(String id,String feature,String detail,String improvement){gaps.add(Map.of("id",id,"feature",feature,"observed",detail,"improvement",improvement));}
 static void phase(String name,Work work){int start=checks.size();System.out.println("WHOLE_PHASE_START "+name);try{work.run();journey.add(Map.of("feature",name,"checks",checks.size()-start,"state","exercised"));System.out.println("WHOLE_PHASE_DONE "+name);}catch(Throwable e){checks.add(Map.of("name",name+" exception","passed",false,"detail",e.toString()));journey.add(Map.of("feature",name,"checks",checks.size()-start,"state","needs attention"));}}
 static void waitFor(java.util.function.BooleanSupplier busy)throws Exception{for(int i=0;i<800;i++){edt(()->{});if(!busy.getAsBoolean()){edt(()->{});return;}Thread.sleep(25);}throw new IllegalStateException("worker deadline");}
 static HttpRequest req(String path,RuntimeUserAudit.Account a){return RuntimeUserAudit.req(path,a);}
 static HttpRequestResponse send(HttpRequest q){nativeSends++;var rr=api.http().sendRequest(q,RequestOptions.requestOptions().withResponseTimeout(6000).withRedirectionMode(RedirectionMode.NEVER));if(rr==null||rr.response()==null)throw new IllegalStateException("no response "+q.url());return rr;}
 static HttpRequestResponse get(String p){return send(req(p,alice));}
 static Engine.Response proxyGet(String p)throws Exception{proxySends++;String request="GET "+base+p+" HTTP/1.1\r\nHost: 127.0.0.1:18299\r\nCookie: "+alice.cookie()+"\r\nConnection: close\r\n\r\n";try(var socket=new Socket()){socket.connect(new InetSocketAddress("127.0.0.1",18288),2000);socket.setSoTimeout(7000);socket.getOutputStream().write(request.getBytes(StandardCharsets.UTF_8));return Engine.parse(socket.getInputStream().readAllBytes());}}
