 static String template(String method,String path,String body,String type){return method+" "+path+" HTTP/1.1\r\nHost: 127.0.0.1:18299\r\nConnection: close\r\nCookie: "+alice.cookie()+"\r\nX-CSRF-Token: "+alice.csrf()+"\r\n"+(type.isEmpty()?"":"Content-Type: "+type+"\r\n")+(body.isEmpty()?"":"Content-Length: "+body.getBytes(StandardCharsets.UTF_8).length+"\r\n")+"\r\n"+body;}
 static byte[] transport(byte[] raw){var q=HttpRequest.httpRequest(HttpService.httpService("127.0.0.1",18299,false),burp.api.montoya.core.ByteArray.byteArray(raw));if(!q.url().startsWith(base+"/"))throw new IllegalArgumentException("owned loopback only");return send(q).response().toByteArray().getBytes();}
